-- 039: Wild Adventures, Valdosta, Georgia (Carter, 2026-10-17, from RCDB, with
-- coordinates 30.719319413969753, -83.32246157958323). Not in D1 before.
-- Six coasters, stats from RCDB. Models follow the site's names: Vekoma
-- Boomerang / SLC / SFC join the Vekoma Boomerangs, Vekoma SLCs and Vekoma
-- SFCs categories (Carter: "make sure the categories for Boomerang and SLC are
-- applied too"; Swamp Thing is the SFC). Former names are undated aliases:
-- Marsh Mayhem was Bug Out (2000-09) and Go Bananas! (2010-22), Outpost
-- Express was Ant Farm Express (2000-18), Twisted Typhoon was Hangman
-- (1999-2011). The /changes rows are the Worker's shapes. Safe to run twice.
INSERT INTO parks (name, lat, lon, region) SELECT 'Wild Adventures', 30.719319413969753, -83.32246157958323, 'Georgia, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Wild Adventures');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Boomerang', 'Wild Adventures', 'Steel', 'Vekoma', 'Vekoma Boomerang', 116.5, 47, 935, 3, 108, 1, 1998, '1998', 'year', NULL, NULL WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Wild Adventures') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Boomerang' AND park = 'Wild Adventures');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Marsh Mayhem', 'Wild Adventures', 'Steel', 'Maurer Rides', 'Maurer Wild Mouse', 49.3, 28, 1213.9, 0, 70, 1, 2000, '2000', 'year', NULL, NULL WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Wild Adventures') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Marsh Mayhem' AND park = 'Wild Adventures');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Outpost Express', 'Wild Adventures', 'Steel', 'Vekoma', 'Vekoma Junior Coaster', 27.9, 21.7, 679.1, 0, 44, 1, 2000, '2000', 'year', NULL, NULL WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Wild Adventures') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Outpost Express' AND park = 'Wild Adventures');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Swamp Thing', 'Wild Adventures', 'Steel', 'Vekoma', 'Vekoma Suspended Family Coaster', 48.6, 26, 1122, 0, 90, 1, 2003, '2003-05-10', 'day', NULL, NULL WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Wild Adventures') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Swamp Thing' AND park = 'Wild Adventures');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Swampwater Snake', 'Wild Adventures', 'Steel', 'Zamperla', 'Zamperla Mini Mouse', 8, NULL, 262, 0, NULL, 1, 2019, '2019', 'year', NULL, NULL WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Wild Adventures') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Swampwater Snake' AND park = 'Wild Adventures');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, laps, yr, opened, openedPrec, closed, closedPrec) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Twisted Typhoon', 'Wild Adventures', 'Steel', 'Vekoma', 'Vekoma Suspended Looping Coaster', 109.3, 49.7, 2260.5, 5, 96, 1, 1999, '1999-05-08', 'day', NULL, NULL WHERE EXISTS (SELECT 1 FROM parks WHERE name = 'Wild Adventures') AND NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Twisted Typhoon' AND park = 'Wild Adventures');
INSERT OR IGNORE INTO clone_members (coaster, group_id) SELECT c.id, g.id FROM coasters c, clone_groups g WHERE g.name = 'Vekoma Boomerangs' AND c.name = 'Boomerang' AND c.park = 'Wild Adventures';
INSERT OR IGNORE INTO clone_members (coaster, group_id) SELECT c.id, g.id FROM coasters c, clone_groups g WHERE g.name = 'Vekoma SLCs' AND c.name = 'Twisted Typhoon' AND c.park = 'Wild Adventures';
INSERT OR IGNORE INTO clone_members (coaster, group_id) SELECT c.id, g.id FROM coasters c, clone_groups g WHERE g.name = 'Vekoma SFCs' AND c.name = 'Swamp Thing' AND c.park = 'Wild Adventures';
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Bug Out', 'rcdb', date('now') FROM coasters WHERE name = 'Marsh Mayhem' AND park = 'Wild Adventures';
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Go Bananas!', 'rcdb', date('now') FROM coasters WHERE name = 'Marsh Mayhem' AND park = 'Wild Adventures';
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Ant Farm Express', 'rcdb', date('now') FROM coasters WHERE name = 'Outpost Express' AND park = 'Wild Adventures';
INSERT OR IGNORE INTO coaster_aliases (coaster_id, former_name, note, added) SELECT id, 'Hangman', 'rcdb', date('now') FROM coasters WHERE name = 'Twisted Typhoon' AND park = 'Wild Adventures';
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.park = 'Wild Adventures' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND a.subject = c.name AND json_extract(a.detail, '$.park') = 'Wild Adventures');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'clone_set', g.name, (SELECT COUNT(*) FROM clone_members m WHERE m.group_id = g.id), json_object('made', 0, 'via', '039') FROM clone_groups g WHERE g.name IN ('Vekoma Boomerangs','Vekoma SLCs','Vekoma SFCs') AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'clone_set' AND a.subject = g.name AND a.detail LIKE '%"via":"039"%');
